using System.IO;using System.Reflection;using System.Text.Json;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Controls;
namespace DanceStudio;
public static class LocalizationTests {
 public static void Run(string output){Directory.CreateDirectory(output);int checks=0;void Check(bool okay,string why){checks++;if(!okay)throw new Exception(why);}
  var ko=UiText.Korean;var en=UiText.English;Check(ko.Keys.Order().SequenceEqual(en.Keys.Order()),"Locale key parity");foreach(var key in ko.Keys){Check(!string.IsNullOrWhiteSpace(en[key]),"Nonempty translation "+key);Check(!Regex.IsMatch(en[key],"[가-힣]"),"English text "+key);Check(Regex.Matches(ko[key],@"\{\d+[^}]*\}").Select(x=>x.Value).SequenceEqual(Regex.Matches(en[key],@"\{\d+[^}]*\}").Select(x=>x.Value)),"Format parity "+key);if(ko[key].Contains('{')){string.Format(System.Globalization.CultureInfo.InvariantCulture,ko[key],Enumerable.Repeat<object>(1.0,32).ToArray());string.Format(System.Globalization.CultureInfo.InvariantCulture,en[key],Enumerable.Repeat<object>(1.0,32).ToArray());}}
  UiText.SettingsPath=Path.Combine(output,"language.json");UiText.SetLanguage("en");Check(UiText.Language=="en","English applied");Check(JsonDocument.Parse(File.ReadAllText(UiText.SettingsPath)).RootElement.GetProperty("language").GetString()=="en","English persisted");UiText.SetLanguage("ko");Check(UiText.T("t0133")=="새 프로젝트","Korean applied");Check(JsonDocument.Parse(File.ReadAllText(UiText.SettingsPath)).RootElement.GetProperty("language").GetString()=="ko","Korean persisted");
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow();app.MainWindow=window;window.Project.Title="User title stays unchanged";window.Project.PlayerYaw=37;window.Project.DanceOutputFps.Mode="Manual";window.Project.DanceOutputFps.Value=24;window.Show();window.UpdateLayout();
  typeof(MainWindow).GetMethod("ChangeLanguage",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,["en"]);var replacement=(MainWindow)app.MainWindow;replacement.UpdateLayout();Check(replacement!=window,"Window rebuilt live");Check(replacement.Project.Title=="User title stays unchanged"&&replacement.Project.PlayerYaw==37&&replacement.Project.DanceOutputFps.Value==24,"Project retained");
  IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var item in Walk(child))yield return item;}
  var buttons=Walk(replacement).OfType<Button>().Select(x=>x.Content as string).ToArray();Check(buttons.Contains("New project")&&buttons.Contains("Export song package"),"English buttons");Check(replacement.Title.Contains(Brand.Version)&&replacement.Title.Contains("Song editor"),"English version title");replacement.Close();app.Shutdown();
  File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{passed=true,checks,version=Brand.Version,resources=ko.Count,liveSwitch=true,gameTested=false},SongProject.Json));
 }
}
